const lead = $('Prep Scraped Data').first().json;
const aiRaw = $input.first().json.output || $input.first().json.text || '';

let ai = {};
try {
  const m = aiRaw.match(/\{[\s\S]*\}/);
  if (m) ai = JSON.parse(m[0]);
} catch(e) {
  ai = {};
}

const social = ai.social_media || {};

return [{
  json: {
    leadId: lead.leadId,
    company: lead.company,
    website: lead.website,
    city: lead.city,
    state: lead.state,
    country: lead.country,
    description: lead.description,
    dm_name: ai.decision_maker_name || '',
    dm_first: ai.first_name || ai.decision_maker_name?.split(' ')[0] || lead.firstName,
    dm_last: ai.last_name || ai.decision_maker_name?.split(' ').slice(1).join(' ') || lead.lastName,
    dm_title: ai.title || lead.existingTitle,
    dm_email: ai.email || lead.existingEmail,
    dm_phone: ai.phone || lead.phone,
    dm_linkedin: ai.linkedin || '',
    num_employees: ai.num_employees || '',
    product_interest: ai.product_interest || 'Unknown',
    specialties: ai.specialties || '',
    confidence: ai.confidence || 'low',
    key_findings: ai.key_findings || '',
    facebook: social.facebook || '',
    twitter: social.twitter || '',
    instagram: social.instagram || '',
    linkedin_company: social.linkedin_company || ''
  }
}];

