let dm = $('Parse DM Result').first().json;

// Try to get updated LinkedIn from the search fallback path
try {
  const linkedinData = $('Extract LinkedIn URL').first().json;
  if (linkedinData.dm_linkedin) dm = { ...dm, dm_linkedin: linkedinData.dm_linkedin };
} catch(e) {
  // LinkedIn was found on website, no search needed
}

const aiRaw = $input.first().json.output || $input.first().json.text || '';

let icp = {};
try {
  const m = aiRaw.match(/\{[\s\S]*\}/);
  if (m) icp = JSON.parse(m[0]);
} catch(e) {
  icp = { icp_score: 0, rating: 'Cold', reasoning: 'Parse error' };
}

// Sanitize values — SF rejects 'Unknown' in email, phone etc.
function clean(v) { return (!v || v === 'Unknown' || v === 'N/A' || v === 'unknown') ? '' : v; }
function cleanEmail(v) { return (!v || !v.includes('@') || v === 'Unknown') ? '' : v; }

const social = [dm.facebook, dm.twitter, dm.instagram, dm.linkedin_company].filter(s => s).join(' | ');
const descParts = [
  dm.description || '',
  '',
  '=== AI ENRICHMENT ===',
  'Decision Maker: ' + (dm.dm_name || 'Unknown') + ' \u2014 ' + (dm.dm_title || 'Unknown'),
  'DM Email: ' + (dm.dm_email || 'N/A'),
  'DM Phone: ' + (dm.dm_phone || 'N/A'),
  'DM LinkedIn: ' + (dm.dm_linkedin || 'N/A'),
  'Employees: ' + (dm.num_employees || 'Unknown'),
  'Specialties: ' + (dm.specialties || 'N/A'),
  'Product Interest: ' + (dm.product_interest || 'Unknown'),
  'Social: ' + (social || 'None found'),
  '',
  '=== ICP SCORE ===',
  'Score: ' + (icp.icp_score || 0) + '/100 (' + (icp.rating || 'Cold') + ')',
  'ICP: ' + (icp.icp_match_score || 0) + ' | Pain: ' + (icp.tech_pain_score || 0) + ' | Intent: ' + (icp.intent_score || 0) + ' | Auth: ' + (icp.authority_score || 0),
  'Product: ' + (icp.product_recommendation || dm.product_interest || 'Unknown'),
  'Reasoning: ' + (icp.reasoning || 'N/A'),
  'Playbook: ' + (icp.playbook || 'N/A'),
  '',
  '=== KEY FINDINGS ===',
  dm.key_findings || 'No findings'
];

return [{
  json: {
    leadId: dm.leadId,
    firstName: dm.dm_first || '',
    lastName: (dm.dm_last || '') + ' - ' + dm.company,
    email: cleanEmail(dm.dm_email),
    title: clean(dm.dm_title),
    phone: clean(dm.dm_phone),
    mobilePhone: clean(dm.dm_phone),
    description: descParts.join('\n'),
    rating: icp.rating || 'Cold',
    status: 'Enriched',
    numberOfEmployees: dm.num_employees || '',
    product_interest: icp.product_recommendation || dm.product_interest || 'Unknown',
    icp_score: icp.icp_score || 0,
    company: dm.company
  }
}];

