const dm = $('Parse DM Result').first().json;
const searchRaw = $input.first().json;

let linkedinUrl = '';
const text = JSON.stringify(searchRaw);

// DDG wraps URLs in redirects like: uddg=https%3A%2F%2Fwww.linkedin.com%2Fin%2Fusername
const uddgMatch = text.match(/uddg=(https?%3A%2F%2F(?:www\.)?linkedin\.com%2Fin%2F[a-zA-Z0-9_-]+)/);
if (uddgMatch) {
  linkedinUrl = decodeURIComponent(uddgMatch[1]);
}

// Fallback: direct LinkedIn URL
if (!linkedinUrl) {
  const directMatch = text.match(/https?:\/\/(?:www\.)?linkedin\.com\/in\/[a-zA-Z0-9_-]+/);
  if (directMatch) linkedinUrl = directMatch[0];
}

// Company page fallback
if (!linkedinUrl) {
  const compUddg = text.match(/uddg=(https?%3A%2F%2F(?:www\.)?linkedin\.com%2Fcompany%2F[a-zA-Z0-9_-]+)/);
  if (compUddg) linkedinUrl = decodeURIComponent(compUddg[1]);
  const compDirect = text.match(/https?:\/\/(?:www\.)?linkedin\.com\/company\/[a-zA-Z0-9_-]+/);
  if (!linkedinUrl && compDirect) linkedinUrl = compDirect[0];
}

return [{
  json: {
    ...dm,
    dm_linkedin: linkedinUrl || dm.dm_linkedin || ''
  }
}];
